'use strict';
const $ = id => document.getElementById(id);
const NS = 'http://www.w3.org/2000/svg';
let contracts, icons = [], profileName = 'SOLO48', shapeName = 'VRECT_L';
const shapeLabels = {CIRCLE:'Circle',SQUARE:'Square',HRECT_XL:'Wide · extra large',HRECT_L:'Wide · large',HRECT_M:'Wide · medium',HRECT_S:'Wide · slim',VRECT_XL:'Tall · extra large',VRECT_L:'Tall · large',VRECT_M:'Tall · medium',VRECT_S:'Tall · slim'};
const familyDescriptions = {sub:'A small glyph, state, modifier, or simple subject that can sit inside another icon.',solo:'A standalone subject with its own silhouette. It neither hosts nor sits inside another icon.',container:'An enclosure or framed device. Draw its real interior details; no region is reserved for hosted content.'};
function node(tag, text, className) { const el=document.createElement(tag); if(text!==undefined)el.textContent=text; if(className)el.className=className; return el; }
function svgNode(tag, attrs={}) { const el=document.createElementNS(NS,tag); for(const [key,value] of Object.entries(attrs))el.setAttribute(key,value); return el; }
function svgText(svg,x,y,text,color='#657266',size=2.2) { const el=svgNode('text',{x,y,fill:color,'font-size':size,'font-family':'ui-monospace, monospace','text-anchor':'middle'});el.textContent=text;svg.append(el); }
function currentProfile(){return contracts.profile.profiles[profileName];}
function currentShape(){return contracts.keyshapes.resolved[profileName][shapeName];}
function dimensionText(shape){return `${shape.width} × ${shape.height}`;}
function envelopeSVG(shape,size,attrs={}) { const [x,y,right,bottom]=shape.visible_bounds;return shapeName==='CIRCLE'?svgNode('circle',{cx:size/2,cy:size/2,r:shape.visible_radius,...attrs}):svgNode('rect',{x,y,width:right-x,height:bottom-y,...attrs}); }
function newCanvas(size,padding=8) { return svgNode('svg',{viewBox:`${-padding} ${-padding} ${size+2*padding} ${size+2*padding}`,role:'img'}); }
function options(select,rows,value){select.replaceChildren();for(const [key,label] of rows){const option=node('option',label);option.value=key;select.append(option);}select.value=value;}
function selectProfile(name){profileName=name;renderFamilies();renderShapes();renderExamples();renderRules();renderStroke();renderGap();saveURL();}
function renderFamilies(){const container=$('families');container.replaceChildren();for(const [name,spec] of Object.entries(contracts.profile.profiles)){const button=node('button');button.type='button';button.setAttribute('aria-pressed',String(name===profileName));button.append(node('strong',spec.family[0].toUpperCase()+spec.family.slice(1)),node('span',`${spec.canvas_size} × ${spec.canvas_size} canvas`));button.onclick=()=>selectProfile(name);container.append(button);}}
function renderShapes(){const shapes=contracts.keyshapes.resolved[profileName];if(!shapes[shapeName])shapeName=Object.keys(shapes)[0];options($('shape'),Object.entries(shapes).map(([name,s])=>[name,`${dimensionText(s)} · ${shapeLabels[name]||name}`]),shapeName);$('atlas').replaceChildren();for(const [name,shape] of Object.entries(shapes)){const size=currentProfile().canvas_size,button=node('button',undefined,'shape-card');button.type='button';button.setAttribute('aria-pressed',String(name===shapeName));button.setAttribute('aria-label',`${shapeLabels[name]}: ${dimensionText(shape)}`);const svg=newCanvas(size,5);svg.setAttribute('aria-hidden','true');svg.append(svgNode('rect',{width:size,height:size,fill:'#e9eee3',stroke:'#ced8c6','stroke-width':.3}));const [x,y,r,b]=shape.visible_bounds;svg.append(svgNode(name==='CIRCLE'?'circle':'rect',name==='CIRCLE'?{cx:size/2,cy:size/2,r:shape.visible_radius,fill:'#d7e3cb',stroke:'#315b3e','stroke-width':.7}:{x,y,width:r-x,height:b-y,fill:'#d7e3cb',stroke:'#315b3e','stroke-width':.7}));button.append(svg,node('strong',dimensionText(shape)),node('span',shapeLabels[name]));button.onclick=()=>{shapeName=name;renderShapes();renderExamples();saveURL();};$('atlas').append(button);}}
function matchingExamples(){return icons.filter(icon=>icon.profile===profileName&&icon.keyshape===shapeName);}
function renderExamples(preferred){const examples=matchingExamples();const selected=examples.some(icon=>icon.key===preferred)?preferred:examples[0]?.key||'';options($('example'),examples.length?examples.map(icon=>[icon.key,icon.name]):[['','No published example for this shape']],selected);$('example').disabled=!examples.length;$('exampleStatus').textContent=examples.length?`${examples.length} published examples for this envelope.`:'The envelope below is a guide; no icon artwork is shown.';renderDrawing();}
function renderDrawing(){const profile=currentProfile(),shape=currentShape(),size=profile.canvas_size,stroke=contracts.profile.style.stroke_width,inset=profile.interior_guide_inset;const icon=icons.find(item=>item.key===$('example').value);const svg=newCanvas(size);svg.setAttribute('aria-label',`${dimensionText(shape)} ${shapeLabels[shapeName]} on a ${size} by ${size} canvas${icon?', showing '+icon.name:''}`);svg.append(svgNode('rect',{width:size,height:size,fill:'#fafbf7',stroke:'#aebaA6','stroke-width':.2}));if($('showGrid').checked){const grid=svgNode('g',{stroke:'#cfdbc6','stroke-width':.08});for(let v=0;v<=size;v+=contracts.profile.style.grid){grid.append(svgNode('line',{x1:v,y1:0,x2:v,y2:size}),svgNode('line',{x1:0,y1:v,x2:size,y2:v}));}svg.append(grid);}if(icon&&$('showIcon').checked){const image=svgNode('image',{href:icon.preview_url,x:0,y:0,width:size,height:size});image.addEventListener('error',()=>{$('drawingNote').textContent='This example SVG could not be loaded. Choose another example.';});svg.append(image);}if($('showGuide').checked)svg.append(svgNode('rect',{x:inset,y:inset,width:size-2*inset,height:size-2*inset,fill:'none',stroke:'#6d8ea9','stroke-width':.25,'stroke-dasharray':'1 1'}));if($('showEnvelope').checked)svg.append(envelopeSVG(shape,size,{fill:'none',stroke:'#c1723d','stroke-width':.35,'stroke-dasharray':'1 .8'}));const [left,top,right,bottom]=shape.visible_bounds;svg.append(svgNode('line',{x1:left,y1:-3,x2:right,y2:-3,stroke:'#c1723d','stroke-width':.2}));for(const x of [left,right])svg.append(svgNode('line',{x1:x,y1:-4,x2:x,y2:-2,stroke:'#c1723d','stroke-width':.2}));svgText(svg,(left+right)/2,-4.5,`${shape.width} wide`);svgText(svg,size/2,size+5,`${shape.height} high · ${size} × ${size} canvas`);$('drawing').replaceChildren(svg);$('canvasLabel').textContent=`${profile.family.toUpperCase()} / ${size} × ${size}`;$('sizeTitle').textContent=dimensionText(shape);$('familyDescription').textContent=familyDescriptions[profile.family];$('drawingNote').textContent=shapeName==='CIRCLE'?`The ink stays inside the circle and reaches within ${contracts.profile.tolerances.circle_touch} units of its radius.`:'The outer ink bounds match the envelope exactly. The stroke is included in these dimensions.';$('measurements').replaceChildren();for(const [name,value] of [['Canvas',`${size} × ${size}`],['Visible ink size',dimensionText(shape)],['Stroke width',`${stroke} units`],['Detail guide inset',`${inset} units`],['Minimum ink gap',`${profile.mic} units`]])$('measurements').append(node('dt',name),node('dd',value));$('inspectLink').hidden=!icon;if(icon)$('inspectLink').href='index.html?'+new URLSearchParams({tab:'icons',q:icon.icon_id,family:icon.family,view:'versions'});}
function renderStroke(){const width=contracts.profile.style.stroke_width,svg=svgNode('svg',{viewBox:'0 0 50 24',role:'img','aria-label':`A ${width} unit stroke extends ${width/2} units on each side of its centerline`});svg.append(svgNode('line',{x1:10,y1:12,x2:38,y2:12,stroke:'#253329','stroke-width':width,'stroke-linecap':'round'}),svgNode('line',{x1:7,y1:12,x2:41,y2:12,stroke:'#e4ad7b','stroke-width':.2,'stroke-dasharray':'.8 .5'}));svgText(svg,25,5,`${width} unit stroke`);svgText(svg,25,21,`${width/2} units on each side of the path`);$('strokeDiagram').replaceChildren(svg);$('strokeExplanation').textContent=`A ${width}-unit stroke extends ${width/2} units to either side of the centerline. A straight edge that touches the envelope needs its centerline ${width/2} units inside that edge.`;}
function spacingResult(gap,profile,stroke){return {valid:gap>=profile.mic,centerline:gap+stroke};}
function renderGap(){const gap=Number($('gap').value),profile=currentProfile(),stroke=contracts.profile.style.stroke_width,result=spacingResult(gap,profile,stroke),color=result.valid?'#315b3e':'#a23e2f';const center=24,x1=center-result.centerline/2,x2=center+result.centerline/2,svg=svgNode('svg',{viewBox:'0 0 48 24',role:'img','aria-label':`${gap} unit ink gap; ${result.valid?'meets':'below'} the ${profile.mic} unit minimum`});for(const x of [x1,x2])svg.append(svgNode('line',{x1:x,y1:5,x2:x,y2:16,stroke:'#253329','stroke-width':stroke,'stroke-linecap':'round'}));if(gap)svg.append(svgNode('rect',{x:x1+stroke/2,y:6,width:gap,height:9,fill:color,opacity:.15}));svgText(svg,24,22,`${gap} ink gap / ${result.centerline} between paths`,color);$('spacingDiagram').replaceChildren(svg);$('gapValue').textContent=`${gap} units`;$('gapResult').dataset.valid=String(result.valid);$('gapResult').textContent=result.valid?`Clearance met · ${gap} ≥ ${profile.mic} units`:`Too close · needs at least ${profile.mic} units`;$('gapExplanation').textContent=`With equal ${stroke}-unit strokes, the centerlines need at least ${profile.equal_stroke_centerline_min} units between them. This checks the illustrated gap only; a complete icon still needs full validation. Intentional joins are different from separate parts.`;}
function renderRules(){const p=currentProfile(),style=contracts.profile.style,tolerance=contracts.profile.tolerances;const rules=[['Use the right canvas',`${p.family[0].toUpperCase()+p.family.slice(1)} icons are authored on ${p.canvas_size} × ${p.canvas_size}. Choose the family by what the icon does. The family fixes its canvas.`],['Keep the stroke consistent',`Use a ${style.stroke_width}-unit stroke with ${style.line_cap} caps and ${style.line_join} joins. The authored stroke stays the same width across the three families.`],['Draw on the unit grid',`Authored coordinates use integers on a ${style.grid}-unit grid. Build contours from lines and elliptical arcs; use connected contours for intentional joins.`],['Fit the visible envelope',`Rectangle-family outer bounds fit exactly. Circular ink stays within the radius and touches within ${tolerance.circle_touch} units. Canvas overflow allowance: ${tolerance.canvas_overflow}.`],['Protect readable gaps',`Keep at least ${p.mic} units of ink-to-ink clearance between distinct parts. Equal-stroke centerlines need ${p.equal_stroke_centerline_min} units. Closed holes and narrow pinches receive additional checks.`],['Use the detail guide correctly',`The internal detail guide is inset ${p.interior_guide_inset} units on this canvas. Full-width and circular silhouettes can still reach the canvas boundary. Containers do not reserve an empty content slot.`]];$('ruleCards').replaceChildren();rules.forEach(([title,text],index)=>{const card=node('article',undefined,'rule-card');card.append(node('span',String(index+1).padStart(2,'0'),'rule-number'),node('h3',title),node('p',text));$('ruleCards').append(card);});}
function saveURL(){const url=new URL(location.href);url.searchParams.set('profile',profileName);url.searchParams.set('shape',shapeName);const example=$('example').value;if(example)url.searchParams.set('icon',example);else url.searchParams.delete('icon');history.replaceState(null,'',url);}
$('shape').onchange=()=>{shapeName=$('shape').value;renderShapes();renderExamples();saveURL();};$('example').onchange=()=>{renderDrawing();saveURL();};for(const id of ['showGrid','showEnvelope','showGuide','showIcon'])$(id).onchange=renderDrawing;$('gap').oninput=renderGap;
async function loadLaboratory(){try{const response=await fetch('laboratory.json');if(!response.ok)throw Error('Design contracts could not be loaded. Refresh this page or rebuild the gallery.');contracts=await response.json();let warning='';try{const catalog=await fetch('icons.json');if(!catalog.ok)throw Error();icons=(await catalog.json()).icons;}catch{warning='Icon examples are unavailable. You can still explore the keyshapes and design rules.';}const params=new URLSearchParams(location.search);if(contracts.profile.profiles[params.get('profile')])profileName=params.get('profile');if(contracts.keyshapes.resolved[profileName][params.get('shape')])shapeName=params.get('shape');renderFamilies();renderShapes();renderExamples(params.get('icon'));$('gap').value=currentProfile().mic;renderRules();renderStroke();renderGap();$('laboratory').hidden=false;$('loadStatus').hidden=!warning;$('loadStatus').textContent=warning;saveURL();}catch(error){$('loadStatus').textContent=error.message||'The Icon Design Rule page could not be loaded. Refresh to try again.';}}
loadLaboratory();
